arguments.command:
python -c "
import parse

# Test R2: digit field numbering with format specs
print('=== R2 Tests (after fix) ===')

try:
    r = parse.parse('{0:d}', '42')
    print(f'parse(\"{{0:d}}\", \"42\") = {r}')
except Exception as e:
    print(f'parse(\"{{0:d}}\", \"42\") raised {type(e).__name__}: {e}')

try:
    r = parse.parse('{0:d}{1:s}', '42 hello')
    print(f'parse(\"{{0:d}}{{1:s}}\", \"42 hello\") = {r}')
except Exception as e:
    print(f'parse(\"{{0:d}}{{1:s}}\", \"42 hello\") raised {type(e).__name__}: {e}')

try:
    r = parse.parse('{0:d}', 'abc')  # Should fail because abc is not an int
    print(f'parse(\"{{0:d}}\", \"abc\") = {r}')
except Exception as e:
    print(f'parse(\"{{0:d}}\", \"abc\") raised {type(e).__name__}: {e}')

# More tests
try:
    r = parse.parse('{0:>10}', 'hello')
    print(f'parse(\"{{0:>10}}\", \"hello\") = {r}')
except Exception as e:
    print(f'parse(\"{{0:>10}}\", \"hello\") raised {type(e).__name__}: {e}')

try:
    r = parse.parse('{0:10d}', '42')
    print(f'parse(\"{{0:10d}}\", \"42\") = {r}')
except Exception as e:
    print(f'parse(\"{{0:10d}}\", \"42\") raised {type(e).__name__}: {e}')
"
